und};\n    -webkit-mask:\n            linear-gradient(#fff 0 0) content-box,\n            linear-gradient(#fff 0 0);\n    -webkit-mask-composite: xor;\n    mask-composite: exclude;\n  }\n}\n\n\n@mixin text-border($thickness, $color) {\n  text-shadow:\n          -#{$thickness}px -#{$thickness}px 0 $color,\n          #{$thickness}px -#{$thickness}px 0 $color,\n          -#{$thickness}px #{$thickness}px 0 $color,\n          #{$thickness}px #{$thickness}px 0 $color;\n}\n\n@mixin headers {\n  .h1, .h2, .h3, .h4, .h5, .h6,h1, h2, h3, h4, h5, h6 {\n    @content;\n  }\n}\n","@use \"../mixins/breakpoint\" as *;\n@use \"../mixins/disable-mob-hover\" as *;\n@use \"../mixins/mini\" as *;\n\n.section-hero {\n  position: relative;\n  z-index: 1;\n  overflow: hidden;\n  margin-bottom: var(--default-padding);\n//   padding: clamp(50px, 8.4028vw, 121px) 0;\n     padding: 16px 0;  \n\n  .swiper-container{\n    width: 100%;\n  }\n\n  .editor {\n    max-width: 706px;\n    width: 100%;\n    gap: clamp(16px, 1.6667vw, 24px);\n\n    .row {\n      justify-content: flex-start;\n      margin-top: 40px;\n\n      .main-button{\n        height: clamp(54px, 4.0972vw, 59px);\n        padding: 16px clamp(24px, 4.4444vw, 64px);\n\n        @include mobile{\n            width: 100%;\n            max-width: 100%;\n        }\n      }\n\n      @include mobile{\n        gap: 16px;\n        max-width: 100%;\n        flex-direction: column;\n        margin-top: auto;\n      }\n    }\n\n   \n\n    p {\n            max-width: clamp(500px, 49.0278vw, 706px);\n      text-align: start;\n      font-family: var(--font-family);\n      font-weight: 500;\n      font-size: clamp(18px, 1.3889vw, 20px);\n      line-height: 145%;\n      color: var(--neutral-100);\n    }\n\n     @include headers {\n            max-width: clamp(500px, 49.0278vw, 706px);\n      text-align: start;\n      color: var(--neutral-100);\n    }\n\n    @include mobile{\n        height: 100%;\n        flex-grow: 1;\n    }\n  }\n\n  &__bg {\n    position: absolute;\n    z-index: -1;\n    inset: 0;\n  }\n\n  .swiper-wrapper{\n        pointer-events: none;\n  }\n\n  &__wrapp{\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    gap: var(--gap);\n    height: fit-content;\n\n    @include for-mobile{\n min-height: calc(clamp(500px, 48.6111vw, 700px) - 32px);\n    }\n\n        @include mobile{\n    min-height: calc(700px - 32px);\n    }\n  }\n\n  &__slider{\n    width: 100%;\n    height: 100%;\n    display: flex;\n  }\n\n  &__slide{\n     width: 100%;\n     display: flex;\n    height: 100%;\n\n    img,\n    picture {\n      width: 100%;\n      height: 100%;\n    }\n  }\n\n  &__image {\n    width: 100%;\n    height: 100%;\n    pointer-events: none;\n    \n    img,\n    picture {\n      width: 100%;\n      height: 100%;\n    }\n  }\n\n  &.mode{\n    padding-bottom: calc(36px + 16px);\n\n    .section-hero__bg{\n        inset: 0 0 calc(36px + 16px);\n    }\n\n    @include mobile{\n          padding-bottom: calc(36px + 16px + 16px);\n    }\n  }\n\n\n}\n","/* stylelint-disable */\n/* stylelint-disable */\n/* stylelint-disable */\n.section-hero {\n  position: relative;\n  z-index: 1;\n  overflow: hidden;\n  margin-bottom: var(--default-padding);\n  padding: 16px 0;\n}\n.section-hero .swiper-container {\n  width: 100%;\n}\n.section-hero .editor {\n  max-width: 706px;\n  width: 100%;\n  gap: clamp(16px, 1.6667vw, 24px);\n}\n.section-hero .editor .row {\n  justify-content: flex-start;\n  margin-top: 40px;\n}\n.section-hero .editor .row .main-button {\n  height: clamp(54px, 4.0972vw, 59px);\n  padding: 16px clamp(24px, 4.4444vw, 64px);\n}\n@media (max-width: 575px) {\n  .section-hero .editor .row .main-button {\n    width: 100%;\n    max-width: 100%;\n  }\n}\n@media (max-width: 575px) {\n  .section-hero .editor .row {\n    gap: 16px;\n    max-width: 100%;\n    flex-direction: column;\n    margin-top: auto;\n  }\n}\n.section-hero .editor p {\n  max-width: clamp(500px, 49.0278vw, 706px);\n  text-ali